        r=af/math.sqrt(3)
        return [(r*math.cos(math.radians(30+60*i)),r*math.sin(math.radians(30+60*i))) for i in range(6)]
    b=cq.Workplane('XY').circle(p.knob_d/2).extrude(p.knob_h)
    for i in range(p.flute_count):
        a=2*math.pi*i/p.flute_count
        b=b.cut(cq.Workplane('XY').center(p.flute_center_r*math.cos(a),p.flute_center_r*math.sin(a)).circle(p.flute_r).extrude(p.knob_h+e))
